def fewest_checks(jobs):
    marks = []
    used = set()
    for start, end, need in sorted(jobs, key=lambda job: (job[1], -job[0])):
        have = sum(1 for m in marks[-5:] if start <= m <= end)
        minute = end
        while have < need:
            if minute not in used:
                used.add(minute)
                marks.append(minute)
                have += 1
            minute -= 1
    return len(marks)

def fewest_checks(jobs):
    if not jobs:
        return 0
    lo = min(s for s, e, need in jobs)
    hi = max(e for s, e, need in jobs)

    def covers(pick):
        return all(sum(s <= m <= e for m in pick) >= need for s, e, need in jobs)

    def search(first, left, pick):
        if left == 0:
            return covers(pick)
        for m in range(first, hi + 1):
            if search(m + 1, left - 1, pick + [m]):
                return True
        return False

    size = 0
    while not search(lo, size, []):
        size += 1
    return size
